const gestureContext=gestureCanvas.getContext('2d');
function gestureStatus(message){$('gestureStatus').textContent=message}
function gestureProgress(){document.querySelectorAll('[data-progress]').forEach(el=>{let ok=gestureState.done.has(el.dataset.progress);el.classList.toggle('complete',ok);el.textContent=(ok?'✓ ':'○ ')+({foto:'Foto',carta:'Carta',corazon:'Corazón'}[el.dataset.progress])});const complete=gestureState.done.size===3;$('gestureDoneText').textContent=complete?'¡Completaste las tres sorpresas! Tu regalo final está desbloqueado. 🎉':'Descubre las 3 sorpresas para desbloquear una celebración especial.';}
function gestureReveal(type){gestureState.done.add(type);gestureProgress();const box=$('gestureReveal');box.classList.remove('hidden');box.classList.remove('heart-win');void box.offsetWidth;box.classList.add('heart-win');const img=$('gestureRevealImg');img.classList.add('hidden');if(type==='foto'){gestureState.photoIndex=PHOTOS.length-1;img.src=PHOTOS[gestureState.photoIndex];img.classList.remove('hidden');$('gestureRevealTitle').textContent='📸 Un pedacito de nosotros';$('gestureRevealText').textContent='Cada fotico guarda un instante en el que fui feliz contigo. Y todavía nos faltan miles por tomar.'}else if(type==='carta'){$('gestureRevealTitle').textContent='💌 Una carta para mi preici';$('gestureRevealText').textContent='Me encanta que nuestra historia empezara con un follow, una noche de patinaje y salchicharrón. Si pudiera repetirlo, volvería a encontrarte.'}else{$('gestureRevealTitle').textContent='💗 Mi corazón es tuyo';$('gestureRevealText').textContent='De Santa Marta a Cartagena, de cada despedida a cada reencuentro: mi lugar favorito sigue siendo contigo.';rain(18)}gestureStatus('¡Sorpresa descubierta! '+(gestureState.done.size===3?'¡Completaste las tres! Ve a tu regalo final.':'Busca la siguiente sorpresa.'));document.querySelector(`[data-gesture-item="${type}"]`)?.classList.add('done');if(gestureState.done.size===3)rain(45)}
document.querySelectorAll('[data-gesture-item]').forEach(el=>el.addEventListener('click',()=>gestureReveal(el.dataset.gestureItem)));

$('gestureReset').onclick=()=>{gestureState.done.clear();gestureProgress();$('gestureReveal').classList.add('hidden');document.querySelectorAll('[data-gesture-item]').forEach(el=>el.classList.remove('done'));gestureStatus('¡Empecemos de nuevo! Descubre las tres sorpresas.')};
$('finalOpen').onclick=()=>{const env=$('finalOpen');env.classList.add('opened');rain(32);setTimeout(()=>openLetter('final'),600)};
function resizeGestureCanvas(){const r=gestureStage.getBoundingClientRect();gestureCanvas.width=Math.max(1,Math.round(r.width*devicePixelRatio));gestureCanvas.height=Math.max(1,Math.round(r.height*devicePixelRatio));gestureContext.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}
function stopGestureCamera(){gestureState.running=false;if(gestureState.raf)cancelAnimationFrame(gestureState.raf);gestureState.raf=0;gestureState.stream?.getTracks().forEach(t=>t.stop());gestureState.stream=null;gestureVideo.srcObject=null;gestureStage.classList.remove('camera-on');gesturePointer.style.display='none';gestureContext.clearRect(0,0,gestureCanvas.width,gestureCanvas.height);$('gestureStart').classList.remove('hidden');$('gestureStop').classList.add('hidden');gestureStatus('Cámara detenida. Puedes seguir jugando con clic o toque.')}
$('gestureStop').onclick=stopGestureCamera;
async function initGestureLandmarker(){if(gestureState.landmarker)return gestureState.landmarker;
let last;for(const base of ['./vendor/tasks-vision','https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21','https://unpkg.com/@mediapipe/tasks-vision@0.10.21']){try{const module=await import(base+'/vision_bundle.mjs').catch(()=>import(base+'/+esm'));const vision=await module.FilesetResolver.forVisionTasks(base+'/wasm');for(const delegate of ['CPU','GPU']){try{gestureState.landmarker=await module.HandLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:base.startsWith('.')?'./vendor/hand_landmarker.task':'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task',delegate},runningMode:'VIDEO',numHands:1});return gestureState.landmarker}catch(e){last=e}}}catch(e){last=e}}throw last||new Error('No se pudo cargar MediaPipe');}
$('gestureStart').onclick=async()=>{if(gestureState.running)return;if(!navigator.mediaDevices?.getUserMedia){gestureStatus('Este navegador no ofrece acceso a cámara. Puedes tocar los regalos para jugar.');return}if(!window.isSecureContext){gestureStatus('La cámara necesita HTTPS o localhost. Publica la página en GitHub Pages.');return}
 $('gestureStart').disabled=true;gestureStatus('Cargando reconocimiento de manos…');try{await initGestureLandmarker();gestureState.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});gestureVideo.srcObject=gestureState.stream;await gestureVideo.play();resizeGestureCanvas();gestureState.running=true;gestureState.lastTime=-1;gestureState.lastInference=0;gestureState.closed=false;gestureState.armed=true;$('gestureStart').classList.add('hidden');$('gestureStop').classList.remove('hidden');gestureStage.classList.add('camera-on');gestureStatus('¡Listo! Apunta a un regalo y haz una pinza para abrirlo.');gestureLoop()}catch(e){gestureState.stream?.getTracks().forEach(t=>t.stop());gestureState.stream=null;gestureStatus('No se pudo iniciar MediaPipe o la cámara: '+(e?.message||String(e))+'. Puedes seguir tocando los regalos.')}finally{$('gestureStart').disabled=false}};
function gestureLoop(now=0){if(!gestureState.running)return;gestureState.raf=requestAnimationFrame(gestureLoop);if(now-gestureState.lastInference<75||gestureVideo.readyState<2)return;gestureState.lastInference=now;
try{const timestamp=gestureVideo.currentTime;if(timestamp===gestureState.lastTime)return;gestureState.lastTime=timestamp;const result=gestureState.landmarker.detectForVideo(gestureVideo,performance.now());const hands=result.landmarks||[];const r=gestureStage.getBoundingClientRect();gestureContext.clearRect(0,0,r.width,r.height);if(!hands.length){gesturePointer.style.display='none';gestureState.closed=false;gestureState.armed=true;gestureState.hover=null;return}
// Se usa la primera mano detectada; el reflejo horizontal coincide con el video espejo.
const pts=hands[0],idx=pts[8],thumb=pts[4],wrist=pts[0],middle=pts[9];const px=(1-idx.x)*r.width,py=idx.y*r.height;gesturePointer.style.display='block';gesturePointer.style.left=px+'px';gesturePointer.style.top=py+'px';
const scale=Math.max(.07,Math.hypot(wrist.x-middle.x,wrist.y-middle.y));const distance=Math.hypot(idx.x-thumb.x,idx.y-thumb.y)/scale;const closed=gestureState.closed?distance<.58:distance<.42;gesturePointer.classList.toggle('pinching',closed);
for(const p of [idx,thumb]){gestureContext.beginPath();gestureContext.arc((1-p.x)*r.width,p.y*r.height,8,0,Math.PI*2);gestureContext.fillStyle='#fff9f6';gestureContext.fill();gestureContext.strokeStyle='#c42e70';gestureContext.lineWidth=3;gestureContext.stroke()}
const hovered=[...document.querySelectorAll('[data-gesture-item]')].find(el=>{const b=el.getBoundingClientRect();const x=r.left+px,y=r.top+py;return x>=b.left-18&&x<=b.right+18&&y>=b.top-18&&y<=b.bottom+18});document.querySelectorAll('[data-gesture-item]').forEach(el=>el.classList.toggle('gaze',el===hovered));
if(closed&&!gestureState.closed&&gestureState.armed){gestureState.armed=false;if(hovered)gestureReveal(hovered.dataset.gestureItem);else gestureStatus('Pinza detectada 👌. Acerca el cursor rosa a un regalo para seleccionarlo.')}
if(!closed&&gestureState.closed)gestureState.armed=true;gestureState.closed=closed;
}catch(e){gestureStatus('Error al leer los gestos: '+(e?.message||String(e))+'. Puedes usar los botones.');stopGestureCamera()}}
window.addEventListener('resize',()=>{if(gestureState.running)resizeGestureCanvas()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&gestureState.running)stopGestureCamera()});window.addEventListener('pagehide',()=>{if(gestureState.running)stopGestureCamera()});gestureProgress();

const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const progressLine=document.createElement('div');progressLine.className='reading-progress';document.body.append(progressLine);
function reading(){progressLine.style.width=(100*scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight))+'%';}
window.addEventListener('scroll',reading,{passive:true});
let lastTrail=0;document.addEventListener('pointermove',e=>{if(reduceMotion||e.pointerType!=='mouse'||performance.now()-lastTrail<45)return;lastTrail=performance.now();const h=document.createElement('span');h.className='trail-heart';h.textContent=Math.random()>.5?'♡':'♥';h.style.left=e.clientX+'px';h.style.top=e.clientY+'px';h.style.fontSize=(12+Math.random()*13)+'px';h.style.setProperty('--dx',(Math.random()*36-18)+'px');h.style.setProperty('--rot',(Math.random()*60-30)+'deg');document.body.append(h);setTimeout(()=>h.remove(),950)},{passive:true});
const photoDialog=document.createElement('dialog');photoDialog.className='dialog photo-dialog';photoDialog.innerHTML='<button class="close" aria-label="Cerrar fotografía">×</button><img alt="Recuerdo de nosotros"><p></p>';document.body.append(photoDialog);photoDialog.querySelector('button').onclick=()=>photoDialog.close();photoDialog.addEventListener('click',e=>{if(e.target===photoDialog)photoDialog.close()});
const sections=[...document.querySelectorAll('main .panel')];let pIndex=1;sections.forEach((section,k)=>{const rail=document.createElement('div');rail.className='side-photos';const count=Math.ceil((PHOTOS.length-2)/sections.length);for(let j=0;j<count&&pIndex<PHOTOS.length-1;j++,pIndex++){const i=pIndex;const f=document.createElement('figure');f.className='polaroid '+(j%2?'right':'left');f.style.top=(j<2?'7%':j<4?'53%':'78%');f.style.setProperty('--tilt',(j%2?5:-6)+'deg');f.tabIndex=0;f.setAttribute('role','button');f.setAttribute('aria-label','Abrir fotografía '+(i+1));const im=document.createElement('img');im.src=PHOTOS[i];im.loading='lazy';im.alt='Recuerdo '+(i+1);const cap=document.createElement('figcaption');cap.textContent=captions[i];f.append(im,cap);const show=()=>{photoDialog.querySelector('img').src=PHOTOS[i];photoDialog.querySelector('p').textContent=captions[i];photoDialog.showModal()};f.onclick=show;f.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}};rail.append(f)}section.prepend(rail)});
