const reasons=['Tu sonrisa coqueta','Cómo me pechichas','Tus ganas de salir adelante','Nuestras conversaciones interminables','La forma en que me dices chiqui','Tu compañía aun desde lejos','Tus abrazos','Que contigo puedo reírme de cualquier bobada'];document.getElementById('garden').innerHTML=reasons.map((r,i)=>`<button class="bloom" aria-label="Descubrir razón ${i+1}">♡</button>`).join('');document.querySelectorAll('.bloom').forEach((b,i)=>b.onclick=()=>{b.textContent='♥';document.getElementById('gardenText').textContent=reasons[i]+' ♡';rain(6)});$('hug').onclick=()=>{rain(35);$('hugText').textContent='Cierra los ojitos, mi preici. Imagínate que estoy ahí abrazándote muy fuerte.'};const vals=['Una cita escogida por ti','Un abrazo larguísimo','Una noche de películas junticos','Un paseo sin afán'];$('coupons').innerHTML=vals.map(v=>`<button class="tile coupon">♡<strong>${v}</strong><span>Toca para reclamar</span></button>`).join('');document.querySelectorAll('.coupon').forEach((b,i)=>b.onclick=()=>{$('couponText').textContent='Vale por: '+vals[i]+'. Canjeable con muchos besitos ♡';rain(8)});
